// ===== 지리 유틸 =====
const toRad = x => x*Math.PI/180;
function hav(a,b){const dLat=toRad(b[0]-a[0]),dLng=toRad(b[1]-a[1]);const h=Math.sin(dLat/2)**2+Math.cos(toRad(a[0]))*Math.cos(toRad(b[0]))*Math.sin(dLng/2)**2;return 2*6371000*Math.asin(Math.sqrt(h))}
const pathLen = cs => cs.reduce((s,p,i)=>i?s+hav(cs[i-1],p):0,0);
function nearestGu(lat,lng){let best=null,bd=1e12;for(const [g,c] of Object.entries(GU_CENTER)){const d=hav([lat,lng],c);if(d<bd){bd=d;best=g}}return {gu:best,dist:bd}}
const inSeoulBox = (lat,lng) => lat>37.413 && lat<37.716 && lng>126.734 && lng<127.270;
const approxSeoul = (lat,lng) => inSeoulBox(lat,lng) && nearestGu(lat,lng).dist < 5500;
// 모양(미터 단위 좌표) → 위경도
function shapeToCoords(center, pts, unitM, rotDeg=0){
  const mx=pts.reduce((s,p)=>s+p[0],0)/pts.length, my=pts.reduce((s,p)=>s+p[1],0)/pts.length;
  const r=toRad(rotDeg), mLat=111320, mLng=111320*Math.cos(toRad(center[0]));
  return pts.map(([x,y])=>{x-=mx;y-=my;const X=x*Math.cos(r)-y*Math.sin(r),Y=x*Math.sin(r)+y*Math.cos(r);
    return [+(center[0]+Y*unitM/mLat).toFixed(6), +(center[1]+X*unitM/mLng).toFixed(6)]});
}
const range = (n,f) => Array.from({length:n},(_,i)=>f(i));
const DOG = [[0,6],[1.2,4.2],[1.2,0],[2,0],[2.2,2],[5,2],[5.2,0],[6,0],[6.2,2.6],[6.4,4.2],[8.4,4.6],[8.2,5.6],[7.2,6.0],[6.9,7.2],[6.4,6.2],[6.0,5.0],[1.2,4.2]];
const HEART = range(41,i=>{const t=i/40*2*Math.PI;return [16*Math.sin(t)**3, 13*Math.cos(t)-5*Math.cos(2*t)-2*Math.cos(3*t)-Math.cos(4*t)]});
const POTATO = [...range(37,i=>{const t=i/36*2*Math.PI;return [5.5*Math.cos(t), 2.2*Math.sin(t)*(1-0.18*Math.cos(t))]}), [6.0,0.3],[6.6,0.9],[6.3,1.4]];

