// 직접 입력한 동네 코스(좌표 없음) → 해당 구 중심 근처 표시용
function pinCourse(area){
  const c = GU_CENTER[area] || GU_CENTER["중구"];
  return {id:"pin-"+area, coords: range(25,i=>{const t=i/24*2*Math.PI;return [c[0]+0.0028*Math.sin(t), c[1]+0.0036*Math.cos(t)]})};
}

// ===== 지도 이미지 (실제 지도 타일 + 경로) =====
const TS = 256;
// Esri World Imagery(위성사진) — API 키 없이 사용 가능 (출처 표기 필요)
const ESRI = "https://server.arcgisonline.com/ArcGIS/rest/services";
const tileURL = (z,x,y) => `${ESRI}/World_Imagery/MapServer/tile/${z}/${y}/${x}`;
function proj(lat,lng){const sl=Math.sin(toRad(lat));return [(lng+180)/360*TS, (0.5-Math.log((1+sl)/(1-sl))/(4*Math.PI))*TS]}
const mapCache = new Map();
function mapSVG(c){
  const key = c.id+":"+c.coords.length;
  if(mapCache.has(key)) return mapCache.get(key);
  const p0 = c.coords.map(([a,b])=>proj(a,b));
  const xs=p0.map(p=>p[0]), ys=p0.map(p=>p[1]);
  const ext = Math.max(Math.max(...xs)-Math.min(...xs), (Math.max(...ys)-Math.min(...ys))*1.45) || 1e-7;
  const z = Math.max(10, Math.min(17, Math.floor(Math.log2(300/ext))));
  const k = 2**z;
  const minX=Math.min(...xs)*k, maxX=Math.max(...xs)*k, minY=Math.min(...ys)*k, maxY=Math.max(...ys)*k;
  const cx=(minX+maxX)/2, cy=(minY+maxY)/2;
  const vbW = Math.max(maxX-minX,(maxY-minY)*1.45)*1.45, vbH = vbW/1.45;
  const x0=cx-vbW*1.1, x1=cx+vbW*1.1, y0=cy-vbH/2-vbW*0.32, y1=cy+vbH/2+vbW*0.32;
  const ox=Math.floor(x0/TS)*TS, oy=Math.floor(y0/TS)*TS;
  let tiles = "";
  for(let tx=Math.floor(x0/TS); tx<=Math.floor(x1/TS); tx++)
    for(let ty=Math.floor(y0/TS); ty<=Math.floor(y1/TS); ty++)
      tiles += `<image href="${tileURL(z,tx,ty)}" x="${tx*TS-ox}" y="${ty*TS-oy}" width="${TS+0.5}" height="${TS+0.5}" onerror="this.remove()"/>`;
  const pts = p0.map(([x,y])=>[x*k-ox, y*k-oy]);
  const d = pts.map((p,i)=>(i?"L":"M")+p[0].toFixed(1)+" "+p[1].toFixed(1)).join("");
  const r = (vbW*0.022).toFixed(1), s=pts[0], e=pts[pts.length-1];
  const loop = hav(c.coords[0], c.coords[c.coords.length-1]) < 60;
  const svg = `<svg viewBox="${(cx-vbW/2-ox).toFixed(1)} ${(cy-vbH/2-oy).toFixed(1)} ${vbW.toFixed(1)} ${vbH.toFixed(1)}" preserveAspectRatio="xMidYMid meet" aria-hidden="true">
    <rect x="-2000" y="-2000" width="6000" height="6000" fill="#1B1F26"/>${tiles}<rect x="-2000" y="-2000" width="6000" height="6000" fill="#0E1116" opacity=".28"/>
    <path class="route" d="${d}" vector-effect="non-scaling-stroke"/>
    ${loop?"":`<circle cx="${e[0].toFixed(1)}" cy="${e[1].toFixed(1)}" r="${r}" fill="#fff" stroke="#0E1116" stroke-width="2.5" vector-effect="non-scaling-stroke"/>`}
    <circle cx="${s[0].toFixed(1)}" cy="${s[1].toFixed(1)}" r="${r}" fill="#C8F94B" stroke="#0E1116" stroke-width="2.5" vector-effect="non-scaling-stroke"/></svg>`;
  mapCache.set(key, svg);
  return svg;
}

// ===== 인터랙티브 지도 (Leaflet) =====
const hasLeaflet = () => typeof window.L !== "undefined";
function leafletMap(el, {center=[37.5465,126.99], zoom=12, interactive=true}={}){
  if(!hasLeaflet()) return null;
  const m = L.map(el,{scrollWheelZoom:false, zoomControl:interactive, dragging:interactive, attributionControl:true}).setView(center,zoom);
  L.tileLayer(`${ESRI}/World_Imagery/MapServer/tile/{z}/{y}/{x}`,{maxNativeZoom:18,maxZoom:19,className:"sat-tiles",
    attribution:'Imagery © <a href="https://www.esri.com">Esri</a> — Esri, Maxar, Earthstar Geographics, GIS User Community'}).addTo(m);
  L.tileLayer(`${ESRI}/Reference/World_Boundaries_and_Places/MapServer/tile/{z}/{y}/{x}`,{maxNativeZoom:18,maxZoom:19,opacity:.9}).addTo(m);
  setTimeout(()=>m.invalidateSize(),60);
  return m;
}
const routeStyle = {color:"#FF7A2F",weight:5,opacity:.95,lineJoin:"round"};
function drawRoute(m, coords){
  const g = L.layerGroup().addTo(m);
  L.polyline(coords,routeStyle).addTo(g);
  if(hav(coords[0],coords[coords.length-1])>=60) L.circleMarker(coords[coords.length-1],{radius:7,color:"#0E1116",weight:3,fillColor:"#fff",fillOpacity:1}).addTo(g);
  L.circleMarker(coords[0],{radius:7,color:"#0E1116",weight:3,fillColor:"#C8F94B",fillOpacity:1}).addTo(g);
  m.fitBounds(L.latLngBounds(coords),{padding:[28,28]});
  return g;
}
// 실제 도로(보행로)에 맞추기 — OSRM 공개 서버 (브라우저에서 호출)
async function snapToRoads(coords){
  let pts = coords;
  if(pts.length>70){const step=Math.ceil(pts.length/70);pts=pts.filter((_,i)=>i%step===0).concat([coords[coords.length-1]])}
  const url = `https://routing.openstreetmap.de/routed-foot/route/v1/foot/${pts.map(p=>p[1].toFixed(6)+","+p[0].toFixed(6)).join(";")}?overview=full&geometries=geojson`;
  const ctrl = new AbortController(); const t=setTimeout(()=>ctrl.abort(),12000);
  try{
    const j = await (await fetch(url,{signal:ctrl.signal})).json();
    if(j.code!=="Ok") throw new Error(j.code);
    return j.routes[0].geometry.coordinates.map(([lng,lat])=>[+lat.toFixed(6),+lng.toFixed(6)]);
  } finally { clearTimeout(t) }
}
// 위치 → 서울 자치구 판정 (OSM 역지오코딩 → 실패 시 자치구 중심 좌표로 근사)
async function detectGu(lat,lng){
  try{
    const ctrl=new AbortController(); const t=setTimeout(()=>ctrl.abort(),6000);
    const r = await fetch(`https://nominatim.openstreetmap.org/reverse?format=jsonv2&lat=${lat}&lon=${lng}&zoom=12&accept-language=ko`,{signal:ctrl.signal});
    clearTimeout(t);
    const j = await r.json(); const vals = Object.values(j.address||{}).map(String);
    const seoul = vals.some(v=>v.includes("서울"));
    const gu = seoul ? AREAS.find(a=>vals.some(v=>v===a||v.endsWith(" "+a))) : null;
    return {seoul: seoul && !!gu, gu, label: j.display_name, source:"osm"};
  }catch{
    const ok = approxSeoul(lat,lng);
    return {seoul: ok, gu: ok ? nearestGu(lat,lng).gu : null, source:"approx"};
  }
}

