const itemImg = i => i.retail ? ((window.IMG_DATA||{})[i.id] || `images/decathlon/${i.id}.jpg`) : "";
const thumb = (i, cls="") => itemImg(i) ? `<img class="${cls}" src="${itemImg(i)}" alt="${esc(i.model)}" loading="lazy" onerror="this.replaceWith(Object.assign(document.createElement('span'),{className:'emo',textContent:'${i.emoji}'}))"/>` : `<span class="emo">${i.emoji}</span>`;
const itemById = id => RENT_ITEMS.find(i=>i.id===id);
const won = n => n.toLocaleString("ko-KR")+"원";
let rentals = store.get("rm3_rentals", []);
const activeRentals = () => rentals.filter(r=>r.status==="예약완료");
// 지점별 재고(데모용 고정값) − 예약된 수량
function stock(hubId, itemId, size=""){
  const base = hash(hubId+itemId+size) % 6;
  const used = activeRentals().filter(r=>r.hubId===hubId).flatMap(r=>r.items).filter(x=>x.id===itemId && (x.size||"")===size).length;
  return Math.max(0, base - used);
}
function hash(s){ return [...String(s)].reduce((h,ch)=>(h*31+ch.charCodeAt(0))>>>0, 7) }
function shoeCount(hubId){ return RENT_ITEMS.filter(i=>i.cat==="러닝화").reduce((s,i)=>s+i.sizes.reduce((t,z)=>t+stock(hubId,i.id,z),0),0) }

